// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 k) public {
        // choose an arbitrary positive multiple of 15 as the block number
        uint256 n = bound(k, 1, 10**9);
        uint256 blk = n * 15;
        vm.roll(blk);
        vm.warp(blk + 1);

        // caller is a funded contract that can receive the payout
        Caller caller = new Caller();
        vm.deal(address(caller), 11 ether);

        caller.callC(c, 10 ether);

        // reference: entire balance transferred out on payout blocks -> 0
        assertTrue(address(c).balance == 0);
    }
}

contract Caller {
    function callC(Roulette c, uint256 amount) external {
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "call failed");
    }
    receive() external payable {}
}
